def near_locus():
    px, py = (pos["x"] + 0.5) * CELL, (pos["y"] + 0.5) * CELL
    best = None
    for l in LOCI:
        d = ((l["s"][0] - px) ** 2 + (l["s"][1] - py) ** 2) ** 0.5
        if d < 110 and (best is None or d < best[0]):
            best = (d, l)
    return best[1] if best else None
